// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 value) public {
        value = bound(value, 0, 1 ether);

        Reverter rev = new Reverter();

        if (address(this).balance < value) {
            vm.deal(address(this), value + 1);
        }
        (bool s, ) = address(c).call{value: value}("");
        require(s);

        bool ok;
        try c.sendMoney(address(rev), value, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
